    iron_glasskilnfurniture = { name = "Železni oprema za steklarske peči", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni oprema za steklarske peči za steklarje." },
    bronze_glasskilnfurniture = { name = "Bronast oprema za steklarske peči", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast oprema za steklarske peči za steklarje." },
    silver_glasskilnfurniture = { name = "Srebrn oprema za steklarske peči", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn oprema za steklarske peči za steklarje." },
    gilded_glasskilnfurniture = { name = "Pozlačen oprema za steklarske peči", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen oprema za steklarske peči za steklarje." },
    jewel_set_glasskilnfurniture = { name = "Draguljast oprema za steklarske peči", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast oprema za steklarske peči za steklarje." },
    royal_sovereign_glasskilnfurniture = { name = "Kraljevski suveren oprema za steklarske peči", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren oprema za steklarske peči z biseri za krono." },
}
local BUILDINGS = {
    glasskilnfurniture_workshop = { name = "Glasskilnfurniture delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glasskilnfurniture_house = { name = "Glasskilnfurniture hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glasskilnfurniture_atelier = { name = "Mojstrski glasskilnfurniture atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glasskilnfurniture_palace = { name = "Suverena glasskilnfurniture palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassKilnFurnitureMaker.ironStock=14; GlassKilnFurnitureMaker.bronzeStock=12; GlassKilnFurnitureMaker.woodStock=12; GlassKilnFurnitureMaker.leatherStock=8; GlassKilnFurnitureMaker.silverStock=8; GlassKilnFurnitureMaker.goldStock=6; GlassKilnFurnitureMaker.jewelStock=4; GlassKilnFurnitureMaker.pearlStock=4
GlassKilnFurnitureMaker.productStock = {}; GlassKilnFurnitureMaker.buildings = {}; GlassKilnFurnitureMaker.maker = nil; GlassKilnFurnitureMaker.activeMaking = {}; GlassKilnFurnitureMaker.totalProducts = 0; GlassKilnFurnitureMaker.dayTimer = 0
function GlassKilnFurnitureMaker.init() GlassKilnFurnitureMaker.ironStock=14; GlassKilnFurnitureMaker.bronzeStock=12; GlassKilnFurnitureMaker.woodStock=12; GlassKilnFurnitureMaker.leatherStock=8; GlassKilnFurnitureMaker.silverStock=8; GlassKilnFurnitureMaker.goldStock=6; GlassKilnFurnitureMaker.jewelStock=4; GlassKilnFurnitureMaker.pearlStock=4; GlassKilnFurnitureMaker.productStock={}; GlassKilnFurnitureMaker.buildings={}; GlassKilnFurnitureMaker.maker=nil; GlassKilnFurnitureMaker.activeMaking={}; GlassKilnFurnitureMaker.totalProducts=0; GlassKilnFurnitureMaker.dayTimer=0; print("[GlassKilnFurnitureMaker] Royal Glass Kiln Furniture Maker System initialized (6 products, 4 buildings)") end
function GlassKilnFurnitureMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassKilnFurnitureMaker.maker={name=n or ("Pečar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pečar najet: %s (spretnost: %d)",GlassKilnFurnitureMaker.maker.name,s),"success") end; return true end
function GlassKilnFurnitureMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassKilnFurnitureMaker.build(id) local ok,e=GlassKilnFurnitureMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassKilnFurnitureMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassKilnFurnitureMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassKilnFurnitureMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassKilnFurnitureMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassKilnFurnitureMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassKilnFurnitureMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassKilnFurnitureMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassKilnFurnitureMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassKilnFurnitureMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassKilnFurnitureMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassKilnFurnitureMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassKilnFurnitureMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassKilnFurnitureMaker.buildings==0 then return false,"Potrebna pečna delavnica" end; if not GlassKilnFurnitureMaker.maker then return false,"Potreben pečar" end; return true end
function GlassKilnFurnitureMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassKilnFurnitureMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassKilnFurnitureMaker.ironStock=GlassKilnFurnitureMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassKilnFurnitureMaker.bronzeStock=GlassKilnFurnitureMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassKilnFurnitureMaker.woodStock=GlassKilnFurnitureMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassKilnFurnitureMaker.leatherStock=GlassKilnFurnitureMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassKilnFurnitureMaker.silverStock=GlassKilnFurnitureMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassKilnFurnitureMaker.goldStock=GlassKilnFurnitureMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassKilnFurnitureMaker.jewelStock=GlassKilnFurnitureMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassKilnFurnitureMaker.pearlStock=GlassKilnFurnitureMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassKilnFurnitureMaker.maker then t=math.max(1,t-math.floor(GlassKilnFurnitureMaker.maker.skill/13)) end; table.insert(GlassKilnFurnitureMaker.activeMaking,{id="glasskilnfurniture_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassKilnFurnitureMaker.completeMaking(m) local q=1.0+(GlassKilnFurnitureMaker.getQualityBonus()/100); if GlassKilnFurnitureMaker.maker then q=q+(GlassKilnFurnitureMaker.maker.skill/140) end; q=math.min(2.5,q); GlassKilnFurnitureMaker.productStock[m.productType]=(GlassKilnFurnitureMaker.productStock[m.productType] or 0)+m.quantity; GlassKilnFurnitureMaker.totalProducts=GlassKilnFurnitureMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassKilnFurnitureMaker.maker then GlassKilnFurnitureMaker.maker.itemsMade=GlassKilnFurnitureMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassKilnFurnitureMaker.maker.skill=math.min(100,GlassKilnFurnitureMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pečnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasskilnfurniture.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassKilnFurnitureMaker.update(dt) if not _G.state then return end; GlassKilnFurnitureMaker.dayTimer=GlassKilnFurnitureMaker.dayTimer+dt; if GlassKilnFurnitureMaker.dayTimer>=30 then GlassKilnFurnitureMaker.dayTimer=0; for i=#GlassKilnFurnitureMaker.activeMaking,1,-1 do local m=GlassKilnFurnitureMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassKilnFurnitureMaker.completeMaking(m); table.remove(GlassKilnFurnitureMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassKilnFurnitureMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassKilnFurnitureMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassKilnFurnitureMaker.getStats() return {ironStock=GlassKilnFurnitureMaker.ironStock,bronzeStock=GlassKilnFurnitureMaker.bronzeStock,woodStock=GlassKilnFurnitureMaker.woodStock,leatherStock=GlassKilnFurnitureMaker.leatherStock,silverStock=GlassKilnFurnitureMaker.silverStock,goldStock=GlassKilnFurnitureMaker.goldStock,jewelStock=GlassKilnFurnitureMaker.jewelStock,pearlStock=GlassKilnFurnitureMaker.pearlStock,productStock=GlassKilnFurnitureMaker.productStock,numBuildings=#GlassKilnFurnitureMaker.buildings,hasMaker=GlassKilnFurnitureMaker.maker~=nil,makerName=GlassKilnFurnitureMaker.maker and GlassKilnFurnitureMaker.maker.name or "—",makerSkill=GlassKilnFurnitureMaker.maker and GlassKilnFurnitureMaker.maker.skill or 0,activeMaking=#GlassKilnFurnitureMaker.activeMaking,totalProducts=GlassKilnFurnitureMaker.totalProducts} end
return GlassKilnFurnitureMaker
